-- Migration Script: Expand PII Column Types for Encrypted User Data
-- 
-- Encrypted values generated by CryptoKit (prefixed with [ENC]:) require ~88 characters,
-- which exceeds the original character varying(50) limit on phone_number and admission_number.
--
-- Run this query in your Supabase SQL Editor:

ALTER TABLE public.users 
    ALTER COLUMN phone_number TYPE TEXT,
    ALTER COLUMN admission_number TYPE TEXT;
